(()=>{const D=window.UI_DESIGN,q=new URLSearchParams(location.search),$=id=>document.getElementById(id);let variant=q.get('variant')||'lumen',screen=q.get('screen')||'home',size=q.get('size')||'desktop',one=false,source=variant==='source';if(source)variant='lumen';function fit(){const w=size==='desktop'?1440:390,h=size==='desktop'?1000:844,r=$('canvas').getBoundingClientRect(),scale=one?1:Math.min((r.width-30)/w,(r.height-30)/h,1);$('designFrame').style.width=w+'px';$('designFrame').style.height=h+'px';$('designFrame').style.transform='scale('+scale+')';$('frameWrap').style.width=w*scale+'px';$('frameWrap').style.height=h*scale+'px';}function render(){const selected=source?'source':variant,file=size==='mobile'&&D.mobileSnapshots.includes(screen)?'mobile-'+screen:['home-devices','home-editor'].includes(screen)?'home':screen,workspace=screen==='home-devices'?'devices':screen==='home-editor'?'editor':'';$('designFrame').src='snapshots/'+file+'.html?variant='+selected+(workspace?'&workspace='+workspace:'');$('variantLabel').textContent=source?'SOURCE / 当前源码':D.themeInfo[variant].name+' / '+D.themeInfo[variant].cn;$('original').classList.toggle('on',source);$('prototypeScreen').innerHTML=(size==='mobile'?D.mobileScreens:Object.keys(D.screenNames)).map(s=>'<option value="'+s+'">'+(D.screenNames[s]||s)+'</option>').join('');$('prototypeScreen').value=screen;$('prototypeSize').value=size;history.replaceState(null,'','?variant='+selected+'&screen='+screen+'&size='+size);fit();}function cycle(delta){source=false;variant=D.themes[(D.themes.indexOf(variant)+delta+D.themes.length)%D.themes.length];render();}$('previous').onclick=()=>cycle(-1);$('next').onclick=()=>cycle(1);$('prototypeScreen').onchange=e=>{screen=e.target.value;render();};$('prototypeSize').onchange=e=>{size=e.target.value;if(size==='mobile'&&!D.mobileScreens.includes(screen))screen='home';if(size==='desktop'&&['home-devices','home-editor'].includes(screen))screen='home';render();};$('original').onclick=()=>{source=!source;render();};$('actualSize').onclick=()=>{one=!one;fit();};window.addEventListener('resize',fit);window.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea,[contenteditable]'))return;if(e.key==='ArrowLeft')cycle(-1);if(e.key==='ArrowRight')cycle(1);});render();})();
